//! SPAWN-15 team-base spawn formations (`server/contracts/spawn_formations.json`,
//! generated by `tools/spawn15_formation.py`). PROJECT POLICY, not history:
//! the original ctf spawn points are server-side and UNKNOWN. Each registry map
//! has, per team, 15 spots around the client's ctf base, facing the enemy base.
//! A slot past the formation is refused; vehicles never share a spot.
use std::{io, sync::OnceLock};
use crate::map_profile091::MapId;

pub const POLICY: &str = "spawn15-team-base-formation-v1";
pub const PER_TEAM: usize = 15;
const FORMATIONS_JSON: &str = include_str!("../../../contracts/spawn_formations.json");
/// Grid spacing is 9 x 12 m; anything closer is a corrupt table.
const MIN_SEPARATION_M: f32 = 8.;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Spot { pub position: [f32; 3], pub yaw: f32 }

fn bad(why: &'static str) -> io::Error { io::Error::new(io::ErrorKind::InvalidData, why) }
fn f(v: &serde_json::Value) -> io::Result<f32> {
    v.as_f64().filter(|x| x.is_finite() && x.abs() <= 2000.).map(|x| x as f32).ok_or_else(|| bad("formation number"))
}

/// Indexed by `MapId`, then team 1/2.
fn table() -> io::Result<&'static Vec<[Vec<Spot>; 2]>> {
    static TABLE: OnceLock<Result<Vec<[Vec<Spot>; 2]>, String>> = OnceLock::new();
    TABLE.get_or_init(|| parse(FORMATIONS_JSON).map_err(|e| e.to_string())).as_ref()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.clone()))
}

fn parse(raw: &str) -> io::Result<Vec<[Vec<Spot>; 2]>> {
    let v: serde_json::Value = serde_json::from_str(raw).map_err(|_| bad("formation JSON"))?;
    if v["version"] != 1 || v["kind"] != "wot091_server_spawn_formations" || v["policy"] != POLICY
        || v["parameters"]["per_team"] != PER_TEAM { return Err(bad("formation header")); }
    let rows = v["maps"].as_array().ok_or_else(|| bad("formation maps"))?;
    let mut out: Vec<Option<[Vec<Spot>; 2]>> = MapId::all().map(|_| None).collect();
    for row in rows {
        let map = MapId::from_asset(row["asset"].as_str().ok_or_else(|| bad("formation asset"))?)?;
        let bases = map.spec().ctf_bases.ok_or_else(|| bad("formation map without ctf bases"))?;
        let teams = row["teams"].as_array().filter(|t| t.len() == 2).ok_or_else(|| bad("formation teams"))?;
        let mut parsed: [Vec<Spot>; 2] = [Vec::new(), Vec::new()];
        for (i, team) in teams.iter().enumerate() {
            let base = [f(&team["base_xz"][0])?, f(&team["base_xz"][1])?];
            let yaw = f(&team["yaw"])?;
            let spots = team["spots"].as_array().filter(|s| s.len() == PER_TEAM).ok_or_else(|| bad("formation spot count"))?;
            if team["team"] != i + 1 || (base[0] - bases[i][0]).abs() > 1e-3 || (base[1] - bases[i][1]).abs() > 1e-3
                || !(-std::f32::consts::PI..=std::f32::consts::PI).contains(&yaw) { return Err(bad("formation team/base")); }
            for spot in spots {
                let position = [f(&spot[0])?, f(&spot[1])?, f(&spot[2])?];
                if spot.as_array().is_none_or(|s| s.len() != 3) { return Err(bad("formation spot")); }
                parsed[i].push(Spot { position, yaw });
            }
        }
        let all = parsed.iter().flatten().collect::<Vec<_>>();
        for (n, a) in all.iter().enumerate() {
            for b in &all[n + 1..] {
                if (a.position[0] - b.position[0]).hypot(a.position[2] - b.position[2]) < MIN_SEPARATION_M {
                    return Err(bad("formation spots overlap"));
                }
            }
        }
        let slot = out.get_mut(map_index(map)).ok_or_else(|| bad("formation map index"))?;
        if slot.replace(parsed).is_some() { return Err(bad("duplicate formation map")); }
    }
    // Every registry map must be placeable; a missing map is a build error.
    out.into_iter().map(|row| row.ok_or_else(|| bad("registry map without formation"))).collect()
}

fn map_index(map: MapId) -> usize { MapId::all().position(|m| m == map).unwrap_or(usize::MAX) }

/// The `index`-th vehicle of `team` (1 or 2) on `map`.
pub fn spot(map: MapId, team: u8, index: usize) -> io::Result<Spot> {
    let teams = table()?.get(map_index(map)).ok_or_else(|| bad("formation map"))?;
    let row = teams.get(usize::from(team).wrapping_sub(1)).ok_or_else(|| bad("formation team"))?;
    row.get(index).copied().ok_or_else(|| bad("formation full: map/team cannot place this many vehicles"))
}

/// Spots for a roster, given each slot's team: the n-th member of a team takes
/// that team's n-th spot. Refuses a roster a team's formation cannot hold.
pub fn placement(map: MapId, teams: &[u8]) -> io::Result<Vec<Spot>> {
    let mut used = [0usize; 2];
    teams.iter().map(|&team| {
        let n = used.get_mut(usize::from(team).wrapping_sub(1)).ok_or_else(|| bad("formation team"))?;
        let spot = spot(map, team, *n)?; *n += 1; Ok(spot)
    }).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn spawn15_every_registry_map_has_two_full_separated_formations_at_its_bases() {
        for map in MapId::all() {
            let bases = map.spec().ctf_bases.unwrap();
            for team in [1u8, 2] {
                let spots = (0..PER_TEAM).map(|n| spot(map, team, n).unwrap()).collect::<Vec<_>>();
                let base = bases[usize::from(team) - 1]; let enemy = bases[2 - usize::from(team)];
                for s in &spots {
                    // Near the own base, facing the enemy base.
                    assert!((s.position[0] - base[0]).hypot(s.position[2] - base[1]) <= 110., "{map:?} {team} {s:?}");
                    let want = (enemy[0] - base[0]).atan2(enemy[1] - base[1]);
                    assert!((s.yaw - want).abs() < 1e-4);
                }
                assert!(spot(map, team, PER_TEAM).is_err());
            }
        }
        assert!(spot(MapId::Karelia, 0, 0).is_err() && spot(MapId::Karelia, 3, 0).is_err());
    }
    #[test]
    fn spawn15_placement_fills_teams_in_slot_order_and_refuses_sixteen() {
        let alternating = (0..30).map(|slot| (slot % 2) as u8 + 1).collect::<Vec<_>>();
        for map in MapId::all() {
            for size in [2usize, 6, 15, 30] {
                let rows = placement(map, &alternating[..size]).unwrap();
                for (slot, s) in rows.iter().enumerate() {
                    assert_eq!(*s, spot(map, alternating[slot], slot / 2).unwrap());
                }
            }
            assert!(placement(map, &[1u8; 16]).is_err());
            assert_eq!(placement(map, &[2u8; 15]).unwrap().len(), 15);
        }
    }
    #[test]
    fn spawn15_table_refuses_overlap_wrong_base_or_short_team() {
        let good: serde_json::Value = serde_json::from_str(FORMATIONS_JSON).unwrap();
        assert!(parse(FORMATIONS_JSON).is_ok());
        let mut overlap = good.clone(); overlap["maps"][0]["teams"][0]["spots"][1] = overlap["maps"][0]["teams"][0]["spots"][0].clone();
        let mut base = good.clone(); base["maps"][1]["teams"][1]["base_xz"][0] = 0.into();
        let mut short = good.clone(); short["maps"][2]["teams"][0]["spots"].as_array_mut().unwrap().pop();
        let mut policy = good.clone(); policy["policy"] = "lab".into();
        let mut missing = good.clone(); missing["maps"].as_array_mut().unwrap().pop();
        for wrong in [overlap, base, short, policy, missing] { assert!(parse(&wrong.to_string()).is_err()); }
    }
}
